/* ===================== BÀI 41 · IN/OUT và 8255 PPI ===================== */
/* Bài 41 · IN/OUT và 8255 PPI (AMTS-EMB-002-M11-L01, X86-041) — sinh bởi tools/author/mpu8086/l41.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P41=[{"label": "Ví dụ: công tắc ra LED qua 8255A", "code": "; Ví dụ 1: 8 công tắc (cổng B) ra 8 LED (cổng A) qua 8255A\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AL, 82H                 ; mode 0: A ra, B vào, C ra\n        OUT     86H, AL                 ; thanh ghi điều khiển (A2 A1 = 11)\n        IN      AL, 82H                 ; đọc 8 công tắc ở cổng B\n        OUT     80H, AL                 ; xuất ra 8 LED ở cổng A\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Mở phần Bo I/O: công tắc đặt sẵn 1010 0101 (A5h). Bấm Từng bước. Sau OUT 86h, 8255A có A ra, B vào; IN AL, 82h đọc A5h; OUT 80h, AL làm 4 LED PA7, PA5, PA2, PA0 sáng. Bật/tắt vài công tắc rồi chạy lại. Đoán trước: sau IN AL, 82h, AL bằng bao nhiêu? Đáp án A5h."}, {"label": "Ví dụ: đèn chạy, cổng trong DX", "code": "; Ví dụ 2: đèn chạy 8 bước, địa chỉ cổng nằm trong DX\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AL, 82H                 ; mode 0: A ra, B vào, C ra\n        OUT     86H, AL\n        MOV     DX, 0080H               ; DX = địa chỉ cổng A\n        MOV     AL, 01H                 ; mẫu đầu: chỉ LED PA0 sáng\n        MOV     CX, 8                   ; 8 bước\nbuoc:\n        OUT     DX, AL                  ; 1 byte mã, 8 chu kỳ\n        ROL     AL, 1                   ; dịch mẫu sang trái một bit\n        LOOP    buoc\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "OUT DX, AL dài 1 byte, 8 chu kỳ (OUT 80h, AL: 2 byte, 10 chu kỳ). Mỗi vòng 8 + 2 + 17 = 27 chu kỳ, 8 vòng 8 × 27 − 12 = 204 (LOOP cuối không nhảy: 5). Đèn sáng lần lượt PA0 … PA7, cuối cùng chỉ PA7 sáng. Đoán trước: sau vòng thứ 3, AL bằng bao nhiêu? Đáp án 08h."}, {"label": "Ví dụ: lập và xóa từng bit PC bằng BSR", "code": "; Ví dụ 3: lập/xóa từng bit cổng C bằng từ BSR\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nketQua  DB      ?                       ; cổng C đọc lại\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AL, 82H                 ; mode 0: A ra, B vào, C ra\n        OUT     86H, AL\n        MOV     AL, 01H                 ; BSR: bit 000 (PC0), D0 = 1: lập\n        OUT     86H, AL\n        MOV     AL, 05H                 ; BSR: bit 010 (PC2), lập\n        OUT     86H, AL\n        MOV     AL, 00H                 ; BSR: bit 000 (PC0), D0 = 0: xóa\n        OUT     86H, AL\n        IN      AL, 84H                 ; đọc lại cổng C\n        MOV     ketQua, AL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Ba từ BSR 01h, 05h, 00h: lập PC0, lập PC2, xóa PC0. LED đỏ PC2 sáng, PC0 tắt. IN AL, 84h đọc lại cổng C (cổng ra, đọc được chốt) = 04h. Đoán trước: sau MOV AL, 05h / OUT 86h, AL, LED đỏ nào sáng? Đáp án PC0 và PC2."}, {"label": "Lỗi: địa chỉ lẻ 81h, 83h kiểu PC", "code": "; Lỗi: dùng địa chỉ liên tiếp như 8255 trên PC 8088\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AL, 82H                 ; mode 0, A ra, B vào\n        OUT     83H, AL                 ; SAI: 83h là địa chỉ lẻ\n        IN      AL, 81H                 ; SAI: 81h cũng lẻ\n        OUT     80H, AL                 ; cổng A vẫn là cổng vào\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: 83h, 81h là địa chỉ lẻ, byte đi trên D8–D15 nên không tới 8255A. Từ điều khiển bị mất, 8255A vẫn ở trạng thái sau RESET (mọi cổng vào); IN AL, 81h đọc FFh; OUT 80h ghi vào chốt nhưng cổng A là cổng vào nên LED tắt. Phần Bo I/O ghi cảnh báo. Sửa: 86h, 82h (Ví dụ 1)."}, {"label": "Bẫy: ghi lại từ chế độ làm tắt LED", "code": "; Bẫy: ghi lại từ chế độ làm tắt LED đang sáng\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AL, 82H                 ; mode 0: A ra, B vào, C ra\n        OUT     86H, AL\n        MOV     AL, 0FFH\n        OUT     80H, AL                 ; 8 LED sáng\n        MOV     AL, 8AH                 ; muốn đổi C cao thành cổng vào\n        OUT     86H, AL                 ; từ chế độ mới xóa mọi chốt ra\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy: ghi từ chọn chế độ lần hai (8Ah, chỉ để đổi C cao thành cổng vào) xóa mọi chốt ra, 8 LED vừa sáng tắt hết. Sửa: chọn đúng chế độ một lần lúc khởi tạo, hoặc xuất lại cổng A sau khi đổi chế độ. Đoán trước: sau lệnh OUT cuối, LED cổng A thế nào? Đáp án tắt hết."}, {"label": "Ví dụ: 4 nút ra 4 LED đỏ ở cổng C", "code": "; Ví dụ 6: 4 nút (PC7-PC4) điều khiển 4 LED đỏ (PC3-PC0)\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AL, 8AH                 ; A ra, B vào, C cao vào, C thấp ra\n        OUT     86H, AL\n        IN      AL, 84H                 ; PC7-PC4 = nút K3-K0\n        MOV     CL, 4\n        SHR     AL, CL                  ; 4 bit nút xuống 4 bit thấp\n        OUT     84H, AL                 ; PC3-PC0 sáng theo nút\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "8Ah: A ra, B vào, C cao vào (nút), C thấp ra (LED đỏ). Nút K2, K0 đặt sẵn là nhấn (0101). IN AL, 84h đọc 50h (bit nút ở PC6, PC4; nửa thấp là cổng ra, đọc chốt 0). SHR AL, CL với CL = 4: 8 + 4 × 4 = 24 chu kỳ. Nhấn/thả nút ở phần Bo I/O rồi chạy lại. Đoán trước: sau SHR AL, CL, AL bằng bao nhiêu? Đáp án 05h."}, {"label": "Bẫy: cổng B đặt là cổng ra", "code": "; Bẫy: đặt cổng B là cổng ra trong khi B nối công tắc\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AL, 80H                 ; SAI: cổng B cũng thành cổng ra\n        OUT     86H, AL\n        IN      AL, 82H                 ; đọc chốt ra (00h), không phải công tắc\n        OUT     80H, AL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy: từ điều khiển 80h đặt cổng B là cổng ra trong khi B nối công tắc (xung đột trên dây; trình mô phỏng cảnh báo). IN AL, 82h đọc chốt ra (00h, vừa bị xóa) chứ không đọc công tắc đang bật hết (FFh), nên LED tắt. Sửa: từ điều khiển 82h."}];
const sim41=makeX86Sim(document.getElementById("x86-l41"),{id:"s41",presets:P41,file:"BAI41.ASM"});
const EX41=[{"t": "LED sáng ngược với công tắc", "d": "Bo I/O của khóa: 8255A ở 80h (PA), 82h (PB), 84h (PC), 86h (điều khiển); PA nối 8 LED, PB nối 8 công tắc. Đặt 8255A ở mode 0 với A ra, B vào; đọc 8 công tắc, đảo mọi bit rồi xuất ra 8 LED (công tắc bật thì LED tắt và ngược lại); ghi byte đã xuất vào biến led. Kết thúc bằng INT 21h hàm 4Ch. Trang chấm theo 8 LED sau khi chạy và biến led.", "start": "; Bài tập 1: LED sáng ngược với công tắc\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nled     DB      ?                       ; byte đã xuất ra cổng A\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AL, 82H                 ; mode 0: A ra, B vào\n        OUT     86H, AL\n        IN      AL, 82H                 ; đọc công tắc\n; TODO: đảo mọi bit, xuất ra cổng A, ghi vào led\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"io": {"sw": 0, "want": {"pa": 255}}, "mem": [{"at": "led", "bytes": [255]}]}, {"io": {"sw": 255, "want": {"pa": 0}}, "mem": [{"at": "led", "bytes": [0]}]}, {"io": {"sw": 15, "want": {"pa": 240}}, "mem": [{"at": "led", "bytes": [240]}]}, {"io": {"sw": 165, "want": {"pa": 90}}, "mem": [{"at": "led", "bytes": [90]}]}, {"io": {"sw": 1, "want": {"pa": 254}}, "mem": [{"at": "led", "bytes": [254]}]}, {"io": {"sw": 128, "want": {"pa": 127}}, "mem": [{"at": "led", "bytes": [127]}]}]}, {"t": "Đếm công tắc đang bật", "d": "Đọc 8 công tắc ở cổng B, đếm số công tắc đang bật (số bit 1, từ 0 tới 8) và hiện số đó dạng nhị phân trên 4 LED đỏ PC3–PC0 (ví dụ 5 công tắc bật → 0101); ghi số đếm vào biến dem. Chọn từ điều khiển sao cho cổng B là cổng vào và nửa thấp cổng C là cổng ra. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 2: đếm công tắc đang bật\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ndem     DB      ?                       ; số công tắc đang bật (0-8)\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n; TODO: từ điều khiển (B vào, C thấp ra), đọc cổng B,\n;       đếm bit 1, xuất ra PC3-PC0, ghi vào dem\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"io": {"sw": 90, "want": {"pcl": 4}}, "mem": [{"at": "dem", "bytes": [4]}]}, {"io": {"sw": 0, "want": {"pcl": 0}}, "mem": [{"at": "dem", "bytes": [0]}]}, {"io": {"sw": 255, "want": {"pcl": 8}}, "mem": [{"at": "dem", "bytes": [8]}]}, {"io": {"sw": 1, "want": {"pcl": 1}}, "mem": [{"at": "dem", "bytes": [1]}]}, {"io": {"sw": 128, "want": {"pcl": 1}}, "mem": [{"at": "dem", "bytes": [1]}]}, {"io": {"sw": 127, "want": {"pcl": 7}}, "mem": [{"at": "dem", "bytes": [7]}]}, {"io": {"sw": 150, "want": {"pcl": 4}}, "mem": [{"at": "dem", "bytes": [4]}]}]}, {"t": "Đèn chạy theo công tắc, nhanh và gọn", "d": "Đọc 8 công tắc thành mẫu đầu s, rồi xuất ra cổng A đúng 8 lần, lần lượt: s, s quay trái 1 bit, s quay trái 2 bit, …, s quay trái 7 bit (ROL). Code mẫu cho kết quả đúng nhưng giữ mẫu và bộ đếm trong bộ nhớ nên chậm và dài. Viết lại để đạt cả giới hạn chu kỳ và giới hạn byte mã. Không ghi gì khác ra cổng A; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 3: đèn chạy theo công tắc, nhanh và gọn\n; Bản này đúng nhưng chậm, dài: mẫu và bộ đếm nằm\n; trong bộ nhớ. Hãy viết lại.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nmau     DB      ?                       ; mẫu đèn hiện tại\ndem     DB      ?                       ; số bước còn lại\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AL, 82H                 ; A ra, B vào\n        OUT     86H, AL\n        IN      AL, 82H                 ; mẫu đầu = công tắc\n        MOV     mau, AL\n        MOV     dem, 8\nlap:\n        MOV     AL, mau\n        OUT     80H, AL                 ; xuất mẫu\n        ROL     mau, 1                  ; quay mẫu ngay trên ô nhớ\n        DEC     dem\n        JNZ     lap\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"io": {"sw": 1, "want": {"paSeq": [1, 2, 4, 8, 16, 32, 64, 128]}}}, {"io": {"sw": 129, "want": {"paSeq": [129, 3, 6, 12, 24, 48, 96, 192]}}}, {"io": {"sw": 0, "want": {"paSeq": [0, 0, 0, 0, 0, 0, 0, 0]}}}, {"io": {"sw": 255, "want": {"paSeq": [255, 255, 255, 255, 255, 255, 255, 255]}}}, {"io": {"sw": 165, "want": {"paSeq": [165, 75, 150, 45, 90, 180, 105, 210]}}}, {"io": {"sw": 60, "want": {"paSeq": [60, 120, 240, 225, 195, 135, 15, 30]}}}], "perf": {"cycles": 295, "bytes": 25}}];
const ex41=makeX86Ex(document.getElementById("ex-l41"),sim41,EX41);
makeX86IO(sim41,{show:["ppi"],presets:[{"sw": 165}, {}, {}, {"sw": 165}, {}, {"btn": 5}, {"sw": 255}],ex:document.getElementById("ex-l41"),exList:EX41,exCur:()=>ex41.cur});

makeQuiz("quiz41","score41",[{"q": "Trên bo I/O của khóa, chương trình ghi 89h vào cổng 86h. 8255A được đặt thế nào?", "o": ["Mode 0: A vào, B vào, C cao ra, C thấp ra", "Mode 0: A ra, B ra, C cao vào, C thấp vào", "Lệnh BSR lập bit PC4 của cổng C", "Mode 1 cho nhóm A, cổng A vào, cổng B ra"], "a": 1, "e": "89h = 1000 1001b: D7 = 1 là từ chọn chế độ; D6 D5 = 00 (mode 0 nhóm A); D4 = 0 → A ra; D3 = 1 → C cao vào; D2 = 0 (mode 0 nhóm B); D1 = 0 → B ra; D0 = 1 → C thấp vào."}, {"q": "Một bo 8086 nối 8255A vào D0–D7, A2 A1 của CPU nối A1 A0 của chip, chip được chọn khi A7–A3 = 10000 và A0 = 0. Thanh ghi điều khiển ở cổng nào?", "o": ["86h", "83h", "03h", "87h"], "a": 0, "e": "Thanh ghi điều khiển là A1 A0 của chip = 11, tức A2 A1 của CPU = 11 và A0 = 0: 1000 0110b = 86h. 83h chỉ đúng khi chip nằm ở địa chỉ liên tiếp (bus 8 bit như PC 8088)."}, {"q": "So sánh <code>OUT 80h, AL<\/code> với <code>OUT DX, AL<\/code> (DX = 0080h) theo bảng chu kỳ 8086. Phát biểu nào đúng?", "o": ["Hai lệnh cùng dài 2 byte và cùng 10 chu kỳ", "OUT DX, AL dài 1 byte, 8 chu kỳ; OUT 80h, AL dài 2 byte, 10 chu kỳ", "OUT DX, AL chỉ dùng được cho cổng trên FFh", "OUT 80h, AL nhanh hơn vì không phải đọc DX"], "a": 1, "e": "OUT DX, AL là EEh (1 byte, 8 chu kỳ); OUT 80h, AL là E6 80 (2 byte, 10 chu kỳ). Dạng DX dùng được cho mọi cổng 0000h–FFFFh, nhưng phải nạp DX trước (MOV DX, 0080h: 3 byte, 4 chu kỳ)."}, {"q": "Cần tắt LED ở PC5 mà không đổi chân nào khác của cổng C. Byte nào ghi vào thanh ghi điều khiển?", "o": ["0Bh", "05h", "0Ah", "20h"], "a": 2, "e": "BSR: D7 = 0, D3 D2 D1 = 101 (bit 5), D0 = 0 (xóa) → 0000 1010b = 0Ah. 0Bh là lập PC5, 05h lập PC2, 20h có D3–D1 = 000 nên xóa PC0."}, {"q": "Chương trình chạy <code>MOV AL, 82h<\/code> · <code>OUT 86h, AL<\/code> · <code>MOV AL, 0FFh<\/code> · <code>OUT 80h, AL<\/code> · <code>MOV AL, 8Ah<\/code> · <code>OUT 86h, AL<\/code>. Sau lệnh cuối, 8 LED cổng A thế nào?", "o": ["Tắt hết, vì ghi từ chọn chế độ xóa mọi chốt ra", "Sáng hết, vì cổng A vẫn là cổng ra và chốt giữ FFh", "Sáng theo nút nhấn, vì C cao vừa thành cổng vào", "Không đổi được, vì 8Ah là một lệnh BSR"], "a": 0, "e": "Theo datasheet 8255A, mỗi lần ghi từ chọn chế độ (D7 = 1) các chốt ra bị xóa về 0 (Ví dụ 5). Muốn LED sáng lại phải OUT ra cổng A lần nữa."}]);

